  // --- ImportProductsCard ---
  "inventory.import.chooseFileAlert": { id: "Pilih file Excel (.xlsx) dulu.", en: "Select an Excel file (.xlsx) first.", ms: "Pilih fail Excel (.xlsx) dahulu.", th: "กรุณาเลือกไฟล์ Excel (.xlsx) ก่อน", fil: "Pumili muna ng Excel file (.xlsx).", vi: "Vui lòng chọn tệp Excel (.xlsx) trước." },
  "inventory.import.title": { id: "Import Produk dari Excel", en: "Import Products from Excel", ms: "Import Produk daripada Excel", th: "นำเข้าสินค้าจาก Excel", fil: "Mag-import ng Produkto mula sa Excel", vi: "Nhập sản phẩm từ Excel" },
  "inventory.import.description": { id: "Tambah banyak produk sekaligus. Download template, isi datanya, lalu upload kembali. Produk dengan SKU yang sudah ada akan di-update (harga/kategori/dll) tanpa mengubah stok — pakai Penyesuaian Barang di tab Produk untuk stok.", en: "Add many products at once. Download the template, fill it in, then upload it back. Products with an existing SKU will be updated (price/category/etc.) without changing stock — use the stock adjustment tool on the Products tab for stock.", ms: "Tambah banyak produk sekali gus. Muat turun templat, isi data, kemudian muat naik semula. Produk dengan SKU sedia ada akan dikemas kini (harga/kategori/dll) tanpa mengubah stok — guna Penyesuaian Barang di tab Produk untuk stok.", th: "เพิ่มสินค้าจำนวนมากในครั้งเดียว ดาวน์โหลดเทมเพลต กรอกข้อมูล แล้วอัปโหลดกลับมา สินค้าที่มี SKU อยู่แล้วจะถูกอัปเดต (ราคา/หมวดหมู่/ฯลฯ) โดยไม่เปลี่ยนสต็อก — ใช้การปรับปรุงสต็อกในแท็บสินค้าเพื่อจัดการสต็อก", fil: "Magdagdag ng maraming produkto nang sabay-sabay. I-download ang template, punan ang data, pagkatapos i-upload ulit. Ang produktong may existing SKU ay ma-a-update (presyo/kategorya/atbp.) nang hindi binabago ang stock — gamitin ang Penyesuaian Barang sa tab na Produkto para sa stock.", vi: "Thêm nhiều sản phẩm cùng lúc. Tải mẫu, điền dữ liệu, rồi tải lên lại. Sản phẩm có SKU đã tồn tại sẽ được cập nhật (giá/danh mục/v.v.) mà không thay đổi tồn kho — dùng công cụ điều chỉnh tồn kho ở tab Sản phẩm để thay đổi tồn kho." },
  "inventory.import.downloadTemplate": { id: "Download Template Excel", en: "Download Excel Template", ms: "Muat Turun Templat Excel", th: "ดาวน์โหลดเทมเพลต Excel", fil: "I-download ang Excel Template", vi: "Tải mẫu Excel" },
