  "inventory.recipe.confirmDelete": { id: 'Hapus resep "{name}"? Produk "{product}" jadi tidak punya BOM lagi (HPP balik ke harga modal manual).', en: 'Delete recipe "{name}"? Product "{product}" will no longer have a BOM (its cost price reverts to the manual cost price).', ms: 'Padam resepi "{name}"? Produk "{product}" tidak lagi mempunyai BOM (harga kos kembali ke harga kos manual).', th: 'ลบสูตร "{name}" หรือไม่? สินค้า "{product}" จะไม่มี BOM อีกต่อไป (ต้นทุนกลับไปใช้ต้นทุนที่กรอกด้วยตนเอง)', fil: 'Burahin ang recipe na "{name}"? Ang produktong "{product}" ay wawalan na ng BOM (babalik ang HPP sa manual na cost price).', vi: 'Xóa công thức "{name}"? Sản phẩm "{product}" sẽ không còn BOM (giá vốn quay về giá vốn nhập thủ công).' },
  "inventory.recipe.createTitle": { id: "Buat Resep / BOM Baru", en: "Create New Recipe / BOM", ms: "Cipta Resepi / BOM Baharu", th: "สร้างสูตร / BOM ใหม่", fil: "Gumawa ng Bagong Recipe / BOM", vi: "Tạo công thức / BOM mới" },
  "inventory.recipe.descPrefix": { id: "Produk hasil resep otomatis masuk kategori ", en: "A recipe's resulting product is automatically placed in the ", ms: "Produk hasil resepi automatik dimasukkan ke kategori ", th: "สินค้าที่ได้จากสูตรจะถูกจัดเข้าหมวดหมู่ ", fil: "Ang produktong resulta ng recipe ay awtomatikong napupunta sa kategoryang ", vi: "Sản phẩm thành phẩm từ công thức sẽ tự động vào danh mục " },
  "inventory.recipe.descBold": { id: "Makanan (food)", en: "Food (food)", ms: "Makanan (food)", th: "อาหาร (food)", fil: "Pagkain (food)", vi: "Đồ ăn (food)" },
  "inventory.recipe.descSuffix": { id: ". Saat terjual, stok bahan baku di bawah ini yang berkurang, bukan stok produk jadinya — HPP dihitung otomatis dari harga modal tiap bahan.", en: " category. When sold, the stock of the ingredients below is what decreases — not the finished product's own stock — and the cost price is calculated automatically from each ingredient's cost.", ms: " kategori. Apabila dijual, stok bahan-bahan di bawah ini yang berkurang, bukan stok produk siap — harga kos dikira automatik daripada harga kos setiap bahan.", th: " เมื่อขาย สต็อกของวัตถุดิบด้านล่างนี้จะลดลง ไม่ใช่สต็อกของสินค้าสำเร็จรูป — ต้นทุนคำนวณอัตโนมัติจากต้นทุนของแต่ละวัตถุดิบ", fil: " category. Kapag nabenta, ang stock ng mga sangkap sa ibaba ang bababa, hindi ang stock ng natapos na produkto — awtomatikong kinakalkula ang HPP mula sa cost price ng bawat sangkap.", vi: " Khi bán, tồn kho của các nguyên liệu bên dưới sẽ giảm, không phải tồn kho của thành phẩm — giá vốn được tính tự động từ giá vốn của từng nguyên liệu." },
