  "inventory.supplierPurchase.needItemAlert": { id: "Tambah minimal 1 item belanja.", en: "Add at least 1 purchased item.", ms: "Tambah sekurang-kurangnya 1 item belian.", th: "เพิ่มรายการซื้ออย่างน้อย 1 รายการ", fil: "Magdagdag ng kahit 1 item na binili.", vi: "Thêm ít nhất 1 mặt hàng mua." },
  "inventory.supplierPurchase.title": { id: "Belanja Supplier", en: "Supplier Purchase", ms: "Belian Pembekal", th: "ซื้อจากซัพพลายเออร์", fil: "Bili sa Supplier", vi: "Mua hàng từ nhà cung cấp" },
  "inventory.supplierPurchase.description": {
    id: "Catat pembelian produk apa pun dari supplier/toko — makanan, minuman, snack, bahan baku, aksesoris, dll (kecuali produk hasil resep/BOM, yang biaya modalnya otomatis dari bahan-bahannya). Ongkos transport, parkir, dan lain-lain otomatis dibagi rata ke harga modal (HPP) tiap item.",
    en: "Record a purchase of any product from a supplier/store — food, drinks, snacks, raw materials, accessories, etc. (except recipe/BOM products, whose cost comes automatically from their ingredients). Transport, parking, and other costs are automatically spread evenly into each item's cost price.",
    ms: "Rekod pembelian sebarang produk daripada pembekal/kedai — makanan, minuman, snek, bahan mentah, aksesori, dll (kecuali produk resepi/BOM, yang kosnya datang secara automatik daripada bahan-bahannya). Kos pengangkutan, parkir, dan lain-lain automatik dibahagi sama rata ke harga kos setiap item.",
    th: "บันทึกการซื้อสินค้าใดก็ได้จากซัพพลายเออร์/ร้านค้า — อาหาร เครื่องดื่ม ขนม วัตถุดิบ อุปกรณ์เสริม ฯลฯ (ยกเว้นสินค้าที่มาจากสูตร/BOM ซึ่งต้นทุนจะคำนวณอัตโนมัติจากวัตถุดิบ) ค่าขนส่ง ค่าจอดรถ และค่าใช้จ่ายอื่นๆ จะถูกเฉลี่ยเข้าต้นทุนของแต่ละรายการโดยอัตโนมัติ",
    fil: "Itala ang pagbili ng kahit anong produkto mula sa supplier/tindahan — pagkain, inumin, snack, sangkap, accessories, atbp. (maliban sa mga produktong resulta ng recipe/BOM, na awtomatikong kinukuha ang gastos mula sa mga sangkap nito). Awtomatikong hinahati nang pantay-pantay ang gastos sa transportasyon, parking, at iba pa papunta sa cost price ng bawat item.",
    vi: "Ghi nhận việc mua bất kỳ sản phẩm nào từ nhà cung cấp/cửa hàng — đồ ăn, thức uống, snack, nguyên liệu thô, phụ kiện, v.v. (trừ sản phẩm từ công thức/BOM, có giá vốn tự động lấy từ nguyên liệu của nó). Chi phí vận chuyển, gửi xe và chi phí khác sẽ tự động được phân bổ đều vào giá vốn của từng mặt hàng.",
  },
  "inventory.supplierPurchase.noSupplierHint": { id: 'Belum ada supplier — tambah dulu di tab "Supplier".', en: 'No suppliers yet — add one first on the "Suppliers" tab.', ms: 'Belum ada pembekal — tambah dahulu di tab "Pembekal".', th: 'ยังไม่มีซัพพลายเออร์ — เพิ่มก่อนที่แท็บ "ซัพพลายเออร์"', fil: 'Wala pang supplier — magdagdag muna sa tab na "Supplier".', vi: 'Chưa có nhà cung cấp — hãy thêm ở tab "Nhà cung cấp" trước.' },
