  "inventory.supplierPurchase.totalLabel": { id: "Total Belanja", en: "Total Purchase", ms: "Jumlah Belian", th: "ยอดซื้อรวม", fil: "Kabuuang Bili", vi: "Tổng tiền mua" },
  "inventory.supplierPurchase.paidNowLabel": { id: "Dibayar cash sekarang (uncheck = hutang ke supplier)", en: "Paid in cash now (uncheck = owed to supplier)", ms: "Dibayar tunai sekarang (nyahtanda = hutang kepada pembekal)", th: "ชำระเงินสดตอนนี้ (ไม่เลือก = เป็นหนี้ซัพพลายเออร์)", fil: "Binayaran ng cash ngayon (i-uncheck = utang sa supplier)", vi: "Đã thanh toán tiền mặt ngay (bỏ chọn = còn nợ nhà cung cấp)" },
  "inventory.supplierPurchase.saveButton": { id: "Simpan Belanja — {amount}", en: "Save Purchase — {amount}", ms: "Simpan Belian — {amount}", th: "บันทึกการซื้อ — {amount}", fil: "I-save ang Bili — {amount}", vi: "Lưu giao dịch mua — {amount}" },
  "inventory.supplierPurchase.savedResult": { id: "Belanja tersimpan — {invoiceNumber}", en: "Purchase saved — {invoiceNumber}", ms: "Belian disimpan — {invoiceNumber}", th: "บันทึกการซื้อแล้ว — {invoiceNumber}", fil: "Na-save ang Bili — {invoiceNumber}", vi: "Đã lưu giao dịch mua — {invoiceNumber}" },
  "inventory.supplierPurchase.newCostSuffix": { id: "— HPP baru per unit", en: "— new cost per unit", ms: "— harga kos baharu setiap unit", th: "— ต้นทุนใหม่ต่อหน่วย", fil: "— bagong HPP kada unit", vi: "— giá vốn mới mỗi đơn vị" },
  "inventory.supplierPurchase.chooseCashBankAlert": { id: "Pilih sumber kas/bank yang dipakai untuk membayar belanja ini.", en: "Select the cash/bank source used to pay for this purchase.", ms: "Pilih sumber tunai/bank yang digunakan untuk membayar belian ini.", th: "เลือกแหล่งเงินสด/ธนาคารที่ใช้จ่ายค่าซื้อนี้", fil: "Pumili ng cash/bank source na ginamit para bayaran ang bili na ito.", vi: "Chọn nguồn tiền mặt/ngân hàng dùng để thanh toán khoản mua này." },
  "inventory.supplierPurchase.cashSourceLabel": { id: "Sumber kas/bank yang dipakai bayar", en: "Cash/bank source used to pay", ms: "Sumber tunai/bank yang digunakan untuk bayar", th: "แหล่งเงินสด/ธนาคารที่ใช้จ่าย", fil: "Cash/bank source na ginamit sa pagbayad", vi: "Nguồn tiền mặt/ngân hàng dùng để trả" },
  "inventory.supplierPurchase.cashSourcePlaceholder": { id: "Pilih akun kas/bank", en: "Select cash/bank account", ms: "Pilih akaun tunai/bank", th: "เลือกบัญชีเงินสด/ธนาคาร", fil: "Pumili ng cash/bank account", vi: "Chọn tài khoản tiền mặt/ngân hàng" },
  "inventory.supplierPurchase.noCashBankHint": { id: "Belum ada akun kas/bank dikonfigurasi — akan pakai default sistem.", en: "No cash/bank account configured yet — the system default will be used.", ms: "Belum ada akaun tunai/bank dikonfigurasi — akan guna lalai sistem.", th: "ยังไม่ได้ตั้งค่าบัญชีเงินสด/ธนาคาร — จะใช้ค่าเริ่มต้นของระบบ", fil: "Wala pang naka-configure na cash/bank account — gagamitin ang default ng system.", vi: "Chưa cấu hình tài khoản tiền mặt/ngân hàng — hệ thống sẽ dùng mặc định." },
  "inventory.supplierPurchase.saving": { id: "Menyimpan...", en: "Saving...", ms: "Menyimpan...", th: "กำลังบันทึก...", fil: "Sine-save...", vi: "Đang lưu..." },
