  "inventory.supplierPurchase.legacyHint": { id: "Invoice lama — rincian item direkonstruksi dari catatan stok, bukan data invoice asli.", en: "Older invoice — line items were reconstructed from stock records, not the original invoice data.", ms: "Invois lama — butiran item dibina semula daripada rekod stok, bukan data invois asal.", th: "ใบแจ้งหนี้เก่า — รายการสินค้าถูกสร้างขึ้นใหม่จากบันทึกสต็อก ไม่ใช่ข้อมูลใบแจ้งหนี้ต้นฉบับ", fil: "Lumang invoice — ang mga item ay na-reconstruct mula sa stock records, hindi mula sa orihinal na invoice data.", vi: "Hóa đơn cũ — các dòng hàng được dựng lại từ hồ sơ kho, không phải dữ liệu hóa đơn gốc." },
  "inventory.supplierPurchase.landedCostShort": { id: "HPP", en: "Cost", ms: "Kos", th: "ต้นทุน", fil: "HPP", vi: "Giá vốn" },
  "inventory.supplierPurchase.legacyNoEdit": { id: "Invoice ini dibuat sebelum fitur edit tersedia, jadi rinciannya tidak bisa dipastikan ulang — hanya bisa dilihat atau dibatalkan.", en: "This invoice was created before the edit feature existed, so its details can't be reliably reconstructed — it can only be viewed or cancelled.", ms: "Invois ini dicipta sebelum ciri edit tersedia, jadi butirannya tidak boleh disahkan semula — hanya boleh dilihat atau dibatalkan.", th: "ใบแจ้งหนี้นี้สร้างก่อนมีฟีเจอร์แก้ไข จึงไม่สามารถยืนยันรายละเอียดใหม่ได้ — ดูได้หรือยกเลิกได้เท่านั้น", fil: "Ginawa ang invoice na ito bago magkaroon ng edit feature, kaya hindi na sigurado ang mga detalye nito — pwede lang itong tingnan o kanselahin.", vi: "Hóa đơn này được tạo trước khi có tính năng chỉnh sửa, nên không thể xác nhận lại chi tiết — chỉ có thể xem hoặc hủy." },
  "inventory.supplierPurchase.editHeading": { id: "Edit Invoice {invoiceNumber}", en: "Edit Invoice {invoiceNumber}", ms: "Edit Invois {invoiceNumber}", th: "แก้ไขใบแจ้งหนี้ {invoiceNumber}", fil: "I-edit ang Invoice {invoiceNumber}", vi: "Sửa hóa đơn {invoiceNumber}" },
  "inventory.supplierPurchase.editHint": { id: "Ubah item/qty/harga di bawah lalu simpan — stok, HPP, dan jurnal lama akan otomatis dikoreksi.", en: "Change the items/qty/price below then save — old stock, cost, and journal entries will be automatically corrected.", ms: "Ubah item/kuantiti/harga di bawah kemudian simpan — stok, kos, dan jurnal lama akan diperbetulkan secara automatik.", th: "แก้ไขรายการ/จำนวน/ราคาด้านล่างแล้วบันทึก — สต็อก ต้นทุน และรายการบัญชีเดิมจะถูกแก้ไขอัตโนมัติ", fil: "Baguhin ang item/qty/presyo sa ibaba pagkatapos i-save — awtomatikong ituwid ang lumang stock, cost, at journal entries.", vi: "Thay đổi mặt hàng/số lượng/giá bên dưới rồi lưu — tồn kho, giá vốn và bút toán cũ sẽ được tự động điều chỉnh." },
  "inventory.supplierPurchase.editEmptyCart": { id: "Belum ada item.", en: "No items yet.", ms: "Belum ada item.", th: "ยังไม่มีรายการ", fil: "Wala pang item.", vi: "Chưa có mặt hàng nào." },
  "inventory.supplierPurchase.editReasonPlaceholder": { id: "Alasan koreksi (opsional)", en: "Reason for correction (optional)", ms: "Sebab pembetulan (pilihan)", th: "เหตุผลในการแก้ไข (ไม่บังคับ)", fil: "Dahilan ng pagwawasto (opsyonal)", vi: "Lý do điều chỉnh (tùy chọn)" },
  "inventory.supplierPurchase.saveEditButton": { id: "Simpan Koreksi", en: "Save Correction", ms: "Simpan Pembetulan", th: "บันทึกการแก้ไข", fil: "I-save ang Pagwawasto", vi: "Lưu điều chỉnh" },
  "inventory.supplierPurchase.editSaved": { id: "Koreksi invoice {invoiceNumber} tersimpan.", en: "Correction to invoice {invoiceNumber} was saved.", ms: "Pembetulan invois {invoiceNumber} disimpan.", th: "บันทึกการแก้ไขใบแจ้งหนี้ {invoiceNumber} แล้ว", fil: "Na-save ang pagwawasto sa invoice {invoiceNumber}.", vi: "Đã lưu điều chỉnh hóa đơn {invoiceNumber}." },
  "inventory.supplierPurchase.confirmDelete": { id: 'Batalkan invoice "{n}"? Stok, HPP, dan jurnal yang terkait akan dikembalikan seperti sebelum invoice ini dibuat. Tidak bisa dibatalkan lagi setelah ini.', en: 'Cancel invoice "{n}"? Related stock, cost, and journal entries will be reverted to how they were before this invoice. This cannot be undone.', ms: 'Batalkan invois "{n}"? Stok, kos, dan jurnal berkaitan akan dikembalikan seperti sebelum invois ini dibuat. Tidak boleh dibuat asal selepas ini.', th: 'ยกเลิกใบแจ้งหนี้ "{n}" หรือไม่? สต็อก ต้นทุน และรายการบัญชีที่เกี่ยวข้องจะถูกคืนสภาพก่อนสร้างใบแจ้งหนี้นี้ ไม่สามารถย้อนกลับได้หลังจากนี้', fil: 'Kanselahin ang invoice "{n}"? Ibabalik ang stock, cost, at journal entries na may kaugnayan sa dating estado bago ito ginawa. Hindi na ito puwedeng bawiin.', vi: 'Hủy hóa đơn "{n}"? Tồn kho, giá vốn và bút toán liên quan sẽ được khôi phục về trạng thái trước khi tạo hóa đơn này. Không thể hoàn tác sau khi thực hiện.' },

